// JWKS cache: keys k1..k3, fetched at t=800, ttl=600 -> fresh until t=1400
const cache = { keys: ['k1', 'k2', 'k3'], fetchedAt: 800, ttl: 600 };
function resolveKid(kid, now) {
  if (now - cache.fetchedAt > cache.ttl) return { ok: false, reason: 'jwks-cache-stale' };
  if (!cache.keys.includes(kid))        return { ok: false, reason: 'kid-not-found' };
  return { ok: true };
}
const EXPECTED_AUD = 'acme-api-public';
const MAX_TTL = 900; // 15-minute budget
function validate(t, now) {
  const r = resolveKid(t.kid, now);
  if (!r.ok) return 'REJECT ' + r.reason;
  if (!t.aud.includes(EXPECTED_AUD)) return 'REJECT aud-mismatch';
  if (t.exp <= now) return 'REJECT expired';
  if (t.exp - t.iat > MAX_TTL) return 'REJECT ttl-over-budget';
  return 'ACCEPT';
}
const now = 1000;
const tokens = [
  { id: 'A valid',        kid: 'k2', aud: ['acme-api-public'],       iat: 700, exp: 1300 },
  { id: 'B rotated-out',  kid: 'k9', aud: ['acme-api-public'],       iat: 700, exp: 1300 },
  { id: 'C cross-tenant', kid: 'k1', aud: ['billing-api'],           iat: 700, exp: 1300 },
  { id: 'D ttl-too-long', kid: 'k3', aud: ['acme-api-public', 'x'],  iat: 0,   exp: 1300 },
];
for (const t of tokens) console.log(t.id + ' -> ' + validate(t, now));
console.log('E after-rotation(k2) -> ' + validate({ kid: 'k2', aud: ['acme-api-public'], iat: 700, exp: 1300 }, 1500));
